{"command": "create", "path": "/workspace/source/apps/customer-service/src/erasure-service.ts", "file_text": "import { v4 as uuid } from 'uuid';
import type pg from 'pg';
import { EVENT_TYPES } from '../../../packages/contracts/src/events.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { addOutboxEvent } from '../../../packages/messaging/src/outbox.js';
import { CustomerRepository } from './repository.js';
import {
  ErasureRepository,
  type ErasureRequestRow,
} from './erasure-repository.js';

export class ErasureService {
  constructor(
    private readonly erasure = new ErasureRepository(),
    private readonly customers = new CustomerRepository(),
  ) {}

  async requestErasure(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<ErasureRequestRow> {
    const customer = await this.customers.find(merchantId, customerId);
    if (!customer) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });

    const existingByCustomer = await this.erasure.findByCustomer(merchantId, customerId);

    return await transaction(async (client) => {
      const idemResult = await client.query<{ request_hash: string; response_status: number | null; response_body: unknown }>(
        `SELECT request_hash, response_status, response_body
         FROM operations.idempotency_keys
         WHERE merchant_id=$1 AND scope='erasure' AND key=$2
         FOR UPDATE`,
        [merchantId, idempotencyKey],
      );
      const idemRow = idemResult.rows[0];
      if (idemRow) {
        const expectedHash = this.idempotencyHash(customerId);
        if (idemRow.request_hash !== expectedHash) {
          throw Object.assign(new Error('idempotency key reused with different customer'), { statusCode: 409 });
        }
        if (idemRow.response_status === null) {
          throw Object.assign(new Error('request with this idempotency key is in progress'), { statusCode: 409 });
        }
        const existing = await this.erasure.findByCustomer(merchantId, customerId);
        if (!existing) throw Object.assign(new Error('erasure_request_not_found'), { statusCode: 500 });
        return existing;
      }

      await client.query(
        `INSERT INTO operations.idempotency_keys(merchant_id, scope, key, request_hash, expires_at)
         VALUES($1, 'erasure', $2, $3, now() + interval '24 hours')`,
        [merchantId, idempotencyKey, this.idempotencyHash(customerId)],
      );

      if (existingByCustomer) return existingByCustomer;

      const erasureRequest = await this.erasure.create(client, merchantId, customerId);

      await addOutboxEvent(client, {
        eventType: EVENT_TYPES.CUSTOMER_ERASURE_REQUESTED,
        aggregateType: 'customer',
        aggregateId: customerId,
        merchantId,
        correlationId: uuid(),
        payload: { customerId, erasureRequestId: erasureRequest.id },
      });

      await client.query(
        `UPDATE operations.idempotency_keys
         SET response_status=202, response_body=$2
         WHERE merchant_id=$1 AND scope='erasure' AND key=$3`,
        [merchantId, JSON.stringify(erasureRequest), idempotencyKey],
      );

      return erasureRequest;
    });
  }

  async getRequest(
    merchantId: string,
    requestId: string,
  ): Promise<ErasureRequestRow | undefined> {
    return this.erasure.findById(merchantId, requestId);
  }

  async processErasure(requestId: string): Promise<void> {
    await transaction(async (client) => {
      const req = await this.erasure.beginProcessing(client, requestId);
      if (!req) return;

      try {
        await this.erasure.anonymizeCustomer(client, req.merchant_id, req.customer_id);
        await this.erasure.removeAddresses(client, req.merchant_id, req.customer_id);
        await this.erasure.anonymizeContacts(client, req.merchant_id, req.customer_id);
        await this.erasure.anonymizePaymentMethods(client, req.merchant_id, req.customer_id);
        await this.erasure.removeProviderCustomerMappings(client, req.merchant_id, req.customer_id);
        await this.erasure.anonymizeProviderSandboxCustomers(client, req.merchant_id, req.customer_id);
        await this.erasure.removeNotificationPreferences(client, req.merchant_id, req.customer_id);
        await this.erasure.anonymizeNotifications(client, req.merchant_id, req.customer_id);
        await this.erasure.anonymizeEmailDeliveries(client, req.merchant_id, req.customer_id);
        await this.erasure.anonymizeAnalyticsEvents(client, req.merchant_id, req.customer_id);
        await this.erasure.anonymizeSupportMessages(client, req.merchant_id, req.customer_id);
        await this.erasure.anonymizeDocumentManifests(client, req.merchant_id, req.customer_id);

        await addOutboxEvent(client, {
          eventType: EVENT_TYPES.CUSTOMER_ERASED,
          aggregateType: 'customer',
          aggregateId: req.customer_id,
          merchantId: req.merchant_id,
          correlationId: uuid(),
          payload: { customerId: req.customer_id, erasureRequestId: req.id },
        });

        await this.erasure.complete(client, req.id);
      } catch (error) {
        const message = error instanceof Error ? error.message.slice(0, 300) : String(error).slice(0, 300);
        await this.erasure.fail(client, req.id, message);
        throw error;
      }
    });
  }

  private idempotencyHash(customerId: string): string {
    const { createHash } = require('node:crypto');
    return createHash('sha256').update(`erasure:${customerId}`).digest('hex');
  }
}"}

